args.command:
node - /tau/in/list.txt <<'EOF'
import { readFileSync } from 'node:fs'
import { notes } from '@fleet/notes'

const ids: number[] = []
for (const line of readFileSync(process.argv[2] ?? '', 'utf8').split('\n').filter(Boolean)) {
  const [text = '', tags = ''] = line.split('#')
  ids.push((await notes.add({ text: text.trim(), tags: tags.split(',').map(tag => tag.trim()).filter(Boolean) })).id)
}
console.log(JSON.stringify(ids))
EOF

